INSERT INTO assignments (id, class_id, title, published, closed_at, created_at) VALUES
  ('a-c15-1', 'c1-5', 'AI 요약 확인 · 자주 하는 실수', true, '2026-11-16 18:00+09', '2026-11-16 09:00+09')
INSERT INTO problems (id, assignment_id, position, title, question, free, answer, concept, solution) VALUES
  ('a-c15-1-p1', 'a-c15-1', 1, '1번 문항', '2x + 3 = 11', false, 'x=4', '등식의 성질·이항', ARRAY['2x + 3 = 11', '2x = 11 - 3', '2x = 8', 'x = 4']),
  ('a-c15-1-p2', 'a-c15-1', 2, '2번 문항', '3x - 5 = -8', false, 'x=-1', '등식의 성질·이항', ARRAY['3x - 5 = -8', '3x = -8 + 5', '3x = -3', 'x = -1']),
  ('a-c15-1-p3', 'a-c15-1', 3, '3번 문항', '7 - 3x = 1', false, 'x=2', '정수 계산·계수 나누기', ARRAY['7 - 3x = 1', '-3x = 1 - 7', '-3x = -6', 'x = 2']),
  ('a-c15-1-p4', 'a-c15-1', 4, '4번 문항', '4x - 9 = -1', false, 'x=2', '등식의 성질·이항', ARRAY['4x - 9 = -1', '4x = -1 + 9', '4x = 8', 'x = 2']),
  ('a-c15-1-p5', 'a-c15-1', 5, '5번 문항', '6x = 18', false, 'x=3', '등식의 성질·이항', ARRAY['6x = 18', 'x = 3']),
  ('a-c15-1-p6', 'a-c15-1', 6, '6번 문항', '2(x + 3) = 14', false, 'x=4', '분배법칙·동류항 정리', ARRAY['2(x + 3) = 14', '2x + 6 = 14', '2x = 14 - 6', '2x = 8', 'x = 4']),
  ('a-c15-1-p7', 'a-c15-1', 7, '7번 문항', '3(x - 2) = 9', false, 'x=5', '분배법칙·동류항 정리', ARRAY['3(x - 2) = 9', '3x - 6 = 9', '3x = 9 + 6', '3x = 15', 'x = 5']),
  ('a-c15-1-p8', 'a-c15-1', 8, '8번 문항', '-(x + 3) = 5', false, 'x=-8', '분배법칙·동류항 정리', ARRAY['-(x + 3) = 5', '-x - 3 = 5', '-x = 5 + 3', '-x = 8', 'x = -8']),
  ('a-c15-1-p9', 'a-c15-1', 9, '9번 문항', '7 - (x - 2) = 4', false, 'x=5', '분배법칙·동류항 정리', ARRAY['7 - (x - 2) = 4', '-x + 9 = 4', '-x = 4 - 9', '-x = -5', 'x = 5']),
  ('a-c15-1-p10', 'a-c15-1', 10, '10번 문항', '3x + 4 = 19', false, 'x=5', '등식의 성질·이항', ARRAY['3x + 4 = 19', '3x = 19 - 4', '3x = 15', 'x = 5']),
  ('a-c15-1-p11', 'a-c15-1', 11, '11번 문항', '절댓값이 3인 수 중에서 양수를 구하세요.', true, '3', '절댓값', ARRAY['절댓값이 3인 수는 3, -3', '그중 양수는 3']),
  ('a-c15-1-p12', 'a-c15-1', 12, '12번 문항', 'x 는 음수이고 x 의 절댓값은 5 예요. x 를 구하세요.', true, 'x=-5', '절댓값', ARRAY['절댓값이 5인 수는 5, -5', 'x 는 음수이므로 x = -5']),
  ('a-c15-1-p13', 'a-c15-1', 13, '13번 문항', '-2 보다 크고 3 보다 작은 정수 중에서 자연수를 모두 구하세요.', true, '1, 2', '정수와 자연수', ARRAY['-2 보다 크고 3 보다 작은 정수는 -1, 0, 1, 2', '그중 자연수는 1, 2']),
  ('a-c15-1-p14', 'a-c15-1', 14, '14번 문항', '사과가 x 개 있고, 배는 사과보다 3개 많아요. 사과와 배가 모두 13개일 때, 배는 몇 개인지 구하세요.', true, '8개', '일차방정식의 활용', ARRAY['x + (x + 3) = 13', '2x = 10', 'x = 5', '배는 x + 3 = 8 (개)']),
  ('a-c15-1-p15', 'a-c15-1', 15, '15번 문항', '형의 나이는 동생 나이의 2배예요. 동생의 나이를 x 살이라 하면 두 사람 나이의 합은 36살이에요. 형의 나이를 구하세요.', true, '24살', '일차방정식의 활용', ARRAY['x + 2x = 36', '3x = 36', 'x = 12', '형은 2x = 24 (살)']),
  ('a-c15-1-p16', 'a-c15-1', 16, '16번 문항', '가로가 세로보다 4 cm 긴 직사각형의 둘레가 32 cm 예요. 세로를 x cm 라 할 때, 가로의 길이를 구하세요.', true, '10 cm', '일차방정식의 활용', ARRAY['2(x + x + 4) = 32', '4x + 8 = 32', 'x = 6', '가로는 x + 4 = 10 (cm)']),
  ('a-c15-1-p17', 'a-c15-1', 17, '17번 문항', 'x = -2 일 때, x² + 3 의 값을 구하세요.', true, '7', '식의 값', ARRAY['(-2)² + 3', '4 + 3 = 7']),
  ('a-c15-1-p18', 'a-c15-1', 18, '18번 문항', 'x = -3 일 때, 2x² 의 값을 구하세요.', true, '18', '식의 값', ARRAY['2 × (-3)²', '2 × 9 = 18']),
  ('a-c15-1-p19', 'a-c15-1', 19, '19번 문항', 'x = -2 일 때, 5 - x 의 값을 구하세요.', true, '7', '식의 값', ARRAY['5 - (-2)', '5 + 2 = 7']),
  ('a-c15-1-p20', 'a-c15-1', 20, '20번 문항', 'x = 3 일 때, 2x + 1 의 값을 구하세요.', true, '7', '식의 값', ARRAY['2 × 3 + 1', '6 + 1 = 7'])
INSERT INTO submissions (id, student_id, problem_id, question, started_at, submitted_at, ocr_lines, status, analysis, teacher) VALUES
  ('demo-c15-s51-1', 's51', 'a-c15-1-p11', '절댓값이 3인 수 중에서 양수를 구하세요.', to_timestamp(1794787800), to_timestamp(1794787860), ARRAY['3, -3'], 'done', '{"correctedLines":["3, -3"],"recognizedAnswer":"3, -3","correct":false,"firstErrorLine":0,"errorType":"CONDITION","concept":"절댓값","reason":"절댓값이 3인 수는 3과 -3으로 맞지만, 문제에서 ''양수를 구하라''고 했으므로 양수 3만 답해야 한다. 학생은 3과 -3을 모두 답으로 적어 조건을 반영하지 않았다.","suggestion":"절댓값이 3인 수를 모두 구한 뒤, 문제에서 요구한 ''양수'' 조건에 맞는 값만 고르는 연습을 해 보세요. ''양수는 0보다 큰 수''라는 뜻을 다시 확인해 보세요.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s51-2', 's51', 'a-c15-1-p12', 'x 는 음수이고 x 의 절댓값은 5 예요. x 를 구하세요.', to_timestamp(1794788040), to_timestamp(1794788115), ARRAY['|x|=5', 'x=5, -5'], 'done', '{"correctedLines":["|x|=5","x=5, -5"],"recognizedAnswer":"x=5, -5","correct":false,"firstErrorLine":1,"errorType":"CONDITION","concept":"절댓값","reason":"x=5, -5 에서 절댓값이 5인 두 수를 모두 구했지만, 문제에서 x 는 음수라는 조건을 반영하지 않아 양수 5도 답에 포함했다.","suggestion":"절댓값이 5인 수는 5와 -5인데, 문제에서 x 가 음수라고 했으니 둘 중 어느 것이 x 인지 다시 확인해 보세요. 조건에 맞는 값만 답으로 고르는 연습을 해보면 좋습니다.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s51-3', 's51', 'a-c15-1-p13', '-2 보다 크고 3 보다 작은 정수 중에서 자연수를 모두 구하세요.', to_timestamp(1794788280), to_timestamp(1794788370), ARRAY['-1, 0, 1, 2'], 'done', '{"correctedLines":["-1, 0, 1, 2"],"recognizedAnswer":"-1, 0, 1, 2","correct":false,"firstErrorLine":0,"errorType":"CONDITION","concept":"정수와 자연수","reason":"정수를 -1, 0, 1, 2로 바르게 구했지만, 그중 자연수만 골라야 한다는 조건을 반영하지 않아 0과 음수인 -1까지 답에 포함했다.","suggestion":"자연수의 정의(1, 2, 3, …)를 다시 확인하고, 구한 정수 중에서 자연수에 해당하는 값만 골라 답하도록 안내한다.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s51-4', 's51', 'a-c15-1-p1', '2x + 3 = 11', to_timestamp(1794788520), to_timestamp(1794788625), ARRAY['2x+3=11', '2x=11-3', '2x=8', 'x=4'], 'done', '{"correctedLines":["2x+3=11","2x=11-3","2x=8","x=4"],"recognizedAnswer":"x=4","correct":true,"firstErrorLine":null,"errorType":"NONE","concept":"등식의 성질·이항","reason":"모든 줄이 검산 결과와 일치하며, 2x+3=11에서 3을 이항해 2x=11-3으로 바꾸고 2x=8, x=4로 정확히 정리했다. 과정상 오류가 없다.","suggestion":"정답이며 과정도 정확하므로, 등식의 성질을 이용해 이항할 때 부호를 바꾸는 이유를 말로 설명해 보게 하면 개념 정리에 도움이 된다.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s52-1', 's52', 'a-c15-1-p14', '사과가 x 개 있고, 배는 사과보다 3개 많아요. 사과와 배가 모두 13개일 때, 배는 몇 개인지 구하세요.', to_timestamp(1794788760), to_timestamp(1794788820), ARRAY['x+(x+3)=13', '2x+3=13', '2x=10', 'x=5'], 'done', '{"correctedLines":["x+(x+3)=13","2x+3=13","2x=10","x=5"],"recognizedAnswer":"x=5","correct":false,"firstErrorLine":3,"errorType":"TARGET","concept":"일차방정식의 활용","reason":"x=5는 사과 개수이고, 문제에서 묻는 것은 배의 개수(x+3)이다. 학생은 사과 개수 5를 배의 개수로 답해 구하는 값을 혼동했다.","suggestion":"방정식으로 구한 x가 무엇을 나타내는지(사과 개수) 다시 확인하게 하고, 문제에서 실제로 묻는 값(배의 개수)을 식에 대입해 답하도록 안내한다.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s52-2', 's52', 'a-c15-1-p15', '형의 나이는 동생 나이의 2배예요. 동생의 나이를 x 살이라 하면 두 사람 나이의 합은 36살이에요. 형의 나이를 구하세요.', to_timestamp(1794789000), to_timestamp(1794789075), ARRAY['x+2x=36', '3x=36', 'x=12'], 'done', '{"correctedLines":["x+2x=36","3x=36","x=12"],"recognizedAnswer":"x=12","correct":false,"firstErrorLine":null,"errorType":"TARGET","concept":"일차방정식의 활용","reason":"x+2x=36 → 3x=36 → x=12 로 방정식을 바르게 풀어 동생의 나이 x=12 를 구했지만, 문제에서 묻는 것은 형의 나이(2x=24)이다. 마지막 줄에 x=12 만 써서 구하는 값(형의 나이)을 답하지 않았다.","suggestion":"방정식을 풀어 x=12 를 구한 뒤, 문제에서 실제로 묻는 값이 무엇인지 다시 확인해 보세요. 형의 나이는 2x 이므로 2×12=24 로 답해야 합니다.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s52-3', 's52', 'a-c15-1-p16', '가로가 세로보다 4 cm 긴 직사각형의 둘레가 32 cm 예요. 세로를 x cm 라 할 때, 가로의 길이를 구하세요.', to_timestamp(1794789240), to_timestamp(1794789330), ARRAY['2(x+x+4)=32', '4x+8=32', '4x=24', 'x=6'], 'done', '{"correctedLines":["2(x+x+4)=32","4x+8=32","4x=24","x=6"],"recognizedAnswer":"x=6","correct":false,"firstErrorLine":3,"errorType":"TARGET","concept":"일차방정식의 활용","reason":"방정식 풀이는 맞지만, 문제에서 묻는 가로의 길이(x+4)를 구하지 않고 x=6을 답으로 썼다. 가로는 x+4=10(cm)이어야 한다.","suggestion":"문제에서 구하라는 값이 세로인지 가로인지 다시 확인해 보세요. x를 구한 뒤 가로 길이 x+4를 계산해 답으로 쓰세요.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s52-4', 's52', 'a-c15-1-p5', '6x = 18', to_timestamp(1794789480), to_timestamp(1794789585), ARRAY['6x=18', 'x=3'], 'done', '{"correctedLines":["6x=18","x=3"],"recognizedAnswer":"x=3","correct":true,"firstErrorLine":null,"errorType":"NONE","concept":"등식의 성질·이항","reason":"6x=18에서 양변을 6으로 나누어 x=3을 얻었고, 검산 결과 해 x=3이 맞으며 앞 줄과 같음으로 표시되어 과정에도 문제가 없다.","suggestion":"정답이므로 추가 지도는 필요하지 않다. 다만 등식의 성질을 이용해 양변을 같은 수로 나누는 과정을 말로 설명해 보게 하면 개념 정리에 도움이 된다.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s53-1', 's53', 'a-c15-1-p6', '2(x + 3) = 14', to_timestamp(1794789720), to_timestamp(1794789780), ARRAY['2(x+3)=14', '2x+3=14', '2x=11', 'x=11/2'], 'done', '{"correctedLines":["2(x+3)=14","2x+3=14","2x=11","x=11/2"],"recognizedAnswer":"x=11/2","correct":false,"firstErrorLine":1,"errorType":"DISTRIBUTE","concept":"분배법칙·동류항 정리","reason":"2(x+3)=14 에서 괄호를 풀 때 2를 x에만 곱하고 3에는 곱하지 않아 2x+3=14 로 잘못 썼다. 2(x+3)은 2x+6이 되어야 한다.","suggestion":"괄호 앞 수를 괄호 안 모든 항에 곱해야 한다는 분배법칙을 확인해 보자. 2(x+3)을 2×x와 2×3으로 나누어 계산해 보게 하면 좋다.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s53-2', 's53', 'a-c15-1-p8', '-(x + 3) = 5', to_timestamp(1794789960), to_timestamp(1794790035), ARRAY['-(x+3)=5', '-x+3=5', '-x=2', 'x=-2'], 'done', '{"correctedLines":["-(x+3)=5","-x+3=5","-x=2","x=-2"],"recognizedAnswer":"x=-2","correct":false,"firstErrorLine":1,"errorType":"PAREN_SIGN","concept":"분배법칙·동류항 정리","reason":"-(x+3)=5 에서 괄호를 풀 때 괄호 앞 음수 부호를 뒤쪽 항 3에 적용하지 않아 -x+3=5 로 잘못 썼다. -(x+3)은 -x-3이 되어야 한다.","suggestion":"괄호 앞에 음수가 있을 때 괄호 안 모든 항의 부호가 바뀐다는 점을 확인해 보자. -(x+3)을 -x-3으로 고쳐 다시 풀어 보면 x=-8이 나온다.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s53-3', 's53', 'a-c15-1-p7', '3(x - 2) = 9', to_timestamp(1794790200), to_timestamp(1794790290), ARRAY['3(x-2)=9', '3x-2=9', '3x=11', 'x=11/3'], 'done', '{"correctedLines":["3(x-2)=9","3x-2=9","3x=11","x=11/3"],"recognizedAnswer":"x=11/3","correct":false,"firstErrorLine":1,"errorType":"DISTRIBUTE","concept":"분배법칙","reason":"3(x-2)=9 에서 괄호를 풀 때 3을 x에만 곱하고 -2에는 곱하지 않아 3x-2=9 로 잘못 썼다. 3(x-2)는 3x-6이 되어야 한다.","suggestion":"괄호 앞 수를 괄호 안의 모든 항에 곱해야 한다는 분배법칙을 확인해 보세요. 3(x-2)를 3×x와 3×(-2)로 나누어 계산해 보게 하면 좋습니다.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s53-4', 's53', 'a-c15-1-p9', '7 - (x - 2) = 4', to_timestamp(1794790440), to_timestamp(1794790545), ARRAY['7-(x-2)=4', '7-x-2=4', '5-x=4', '-x=-1', 'x=1'], 'done', '{"correctedLines":["7-(x-2)=4","7-x-2=4","5-x=4","-x=-1","x=1"],"recognizedAnswer":"x=1","correct":false,"firstErrorLine":1,"errorType":"PAREN_SIGN","concept":"분배법칙·동류항 정리","reason":"7-(x-2)=4 에서 괄호 앞 ''-''를 풀 때 뒤쪽 항 -2의 부호를 바꾸지 않아 7-x-2=4 로 잘못 썼다. 괄호 앞 음수는 괄호 안 모든 항의 부호를 바꾸어야 하므로 7-x+2=4 가 맞다.","suggestion":"괄호 앞에 ''-''가 있을 때 괄호 안 각 항의 부호가 어떻게 바뀌는지 직접 써 보며 확인해 보게 한다. 7-(x-2)를 7-x+2로 고친 뒤 다시 풀어 보도록 안내한다.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s53-5', 's53', 'a-c15-1-p1', '2x + 3 = 11', to_timestamp(1794790680), to_timestamp(1794790800), ARRAY['2x+3=11', '2x=11-3', '2x=8', 'x=4'], 'done', '{"correctedLines":["2x+3=11","2x=11-3","2x=8","x=4"],"recognizedAnswer":"x=4","correct":true,"firstErrorLine":null,"errorType":"NONE","concept":"등식의 성질·이항","reason":"모든 줄에서 등식의 성질을 올바르게 적용하여 2x+3=11 → 2x=11-3 → 2x=8 → x=4 로 정확히 풀었다. 마지막 줄의 답도 정답과 일치한다.","suggestion":"풀이 과정이 정확하고 답도 맞으므로, 이 문항에서는 별도의 보충 지도보다 학생이 사용한 이항과 동류항 정리 과정을 스스로 설명하게 하여 이해를 확인해 보는 것이 좋다.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s54-1', 's54', 'a-c15-1-p17', 'x = -2 일 때, x² + 3 의 값을 구하세요.', to_timestamp(1794790920), to_timestamp(1794790980), ARRAY['-2²+3', '=-4+3', '=-1'], 'done', '{"correctedLines":["-2²+3","=-4+3","=-1"],"recognizedAnswer":"-1","correct":false,"firstErrorLine":0,"errorType":"SUBSTITUTE","concept":"식의 값","reason":"x = -2 를 x² 에 대입할 때 괄호를 쓰지 않고 -2² 로 써서 (-2)² = 4 가 아닌 -4 로 계산했다. 그 결과 -4 + 3 = -1 이 되어 정답 7 과 달라졌다.","suggestion":"음수를 제곱할 때는 반드시 괄호를 써서 (-2)² 로 계산하도록 확인해 보세요. (-2)² 와 -2² 의 차이를 직접 계산해 비교해 보면 도움이 됩니다.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s54-2', 's54', 'a-c15-1-p18', 'x = -3 일 때, 2x² 의 값을 구하세요.', to_timestamp(1794791160), to_timestamp(1794791235), ARRAY['2×-3²', '=2×-9', '=-18'], 'done', '{"correctedLines":["2x-3²","=2x-9","=-18"],"recognizedAnswer":"-18","correct":false,"firstErrorLine":0,"errorType":"SUBSTITUTE","concept":"식의 값","reason":"x = -3 을 2x² 에 대입할 때 괄호를 쓰지 않아 2 × (-3)² 가 아니라 2 × -3² 로 썼다. 그 결과 (-3)² = 9 가 아니라 -3² = -9 로 계산해 2 × (-9) = -18 이 됐다.","suggestion":"음수를 제곱할 때는 괄호를 써서 (-3)² 로 계산하도록 확인해 보세요. 2 × (-3)² 와 2 × -3² 의 차이를 직접 계산해 비교해 보면 좋습니다.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s54-3', 's54', 'a-c15-1-p19', 'x = -2 일 때, 5 - x 의 값을 구하세요.', to_timestamp(1794791400), to_timestamp(1794791490), ARRAY['5-2', '=3'], 'done', '{"correctedLines":["5-2","=3"],"recognizedAnswer":"3","correct":false,"firstErrorLine":0,"errorType":"SUBSTITUTE","concept":"식의 값","reason":"x = -2 를 5 - x 에 대입할 때 괄호를 쓰지 않아 5 - (-2) 대신 5 - 2 로 잘못 썼다. 그 결과 5 + 2 = 7 이 되어야 하는데 3 으로 계산했다.","suggestion":"음수를 대입할 때는 괄호를 써서 5 - (-2) 로 써 보게 하세요. 그다음 5 - (-2) = 5 + 2 = 7 임을 확인하게 하세요.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s54-4', 's54', 'a-c15-1-p20', 'x = 3 일 때, 2x + 1 의 값을 구하세요.', to_timestamp(1794791640), to_timestamp(1794791745), ARRAY['2×3+1', '=6+1', '=7'], 'done', '{"correctedLines":["2x3+1","=6+1","=7"],"recognizedAnswer":"7","correct":true,"firstErrorLine":null,"errorType":"NONE","concept":"식의 값","reason":"x = 3 을 2x + 1 에 대입하여 2 × 3 + 1 = 6 + 1 = 7 로 바르게 계산했다. 과정에도 오류가 없다.","suggestion":"대입할 때 곱셈을 먼저 하는 순서를 잘 지켰다. 다음에는 괄호가 필요한 음수 대입 상황에서도 괄호를 쓰는 습관을 확인해 보자.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s55-1', 's55', 'a-c15-1-p2', '3x - 5 = -8', to_timestamp(1794791880), to_timestamp(1794791940), ARRAY['3x-5=-8', '3x=-8+5', '3x=-13', 'x=-13/3'], 'done', '{"correctedLines":["3x-5=-8","3x=-8+5","3x=-13","x=-13/3"],"recognizedAnswer":"x=-13/3","correct":false,"firstErrorLine":2,"errorType":"SIGN","concept":"등식의 성질·이항","reason":"3x = -8 + 5 에서 -8 + 5 를 -13 으로 잘못 계산했다. 맞는 값은 -3 이므로 3x = -3 이 되어야 한다.","suggestion":"음수가 섞인 덧셈·뺄셈을 다시 확인해 보자. -8 + 5 는 수직선에서 -8 에서 5 만큼 오른쪽으로 가는 값인데, 그 결과가 무엇인지 생각해 보자.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s55-2', 's55', 'a-c15-1-p3', '7 - 3x = 1', to_timestamp(1794792120), to_timestamp(1794792195), ARRAY['7-3x=1', '-3x=1-7', '-3x=-8', 'x=8/3'], 'done', '{"correctedLines":["7-3x=1","-3x=1-7","-3x=-8","x=8/3"],"recognizedAnswer":"x=8/3","correct":false,"firstErrorLine":2,"errorType":"SIGN","concept":"정수 계산·계수 나누기","reason":"1-7을 계산할 때 -6이 되어야 하는데 -8로 잘못 계산했다. 이로 인해 -3x=-8이 되어 x=8/3이라는 틀린 답이 나왔다.","suggestion":"1-7을 다시 계산해 보고, 음수가 포함된 뺄셈에서 부호를 어떻게 처리하는지 확인해 보자. -3x=-6에서 양변을 -3으로 나누면 x=2가 됨을 함께 점검해 보자.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s55-3', 's55', 'a-c15-1-p2', '3x - 5 = -8', to_timestamp(1794792360), to_timestamp(1794792450), ARRAY['3x-5=-8', '3x=-8+5', '3x=-3', 'x=-1'], 'done', '{"correctedLines":["3x-5=-8","3x=-8+5","3x=-3","x=-1"],"recognizedAnswer":"x=-1","correct":true,"firstErrorLine":null,"errorType":"NONE","concept":"등식의 성질·이항","reason":"풀이의 모든 줄이 해설과 일치하며, 3x - 5 = -8 에서 5를 이항해 3x = -8 + 5 로 바꾸고 3x = -3, x = -1 로 정확히 구했다. 마지막 줄의 답도 정답과 같다.","suggestion":"이항과 동류항 정리가 잘 되어 있으므로, 음수 계수로 나누는 단계나 괄호가 있는 식에서도 같은 흐름을 유지할 수 있는지 비슷한 문제로 확인해 보면 좋다.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s55-4', 's55', 'a-c15-1-p3', '7 - 3x = 1', to_timestamp(1794792600), to_timestamp(1794792705), ARRAY['7-3x=1', '-3x=1-7', '-3x=-6', 'x=2'], 'done', '{"correctedLines":["7-3x=1","-3x=1-7","-3x=-6","x=2"],"recognizedAnswer":"x=2","correct":true,"firstErrorLine":null,"errorType":"NONE","concept":"정수 계산·계수 나누기","reason":"7 - 3x = 1 에서 3x를 이항해 -3x = 1 - 7 로 바꾸고, 1 - 7 = -6 을 정확히 계산했으며, -3x = -6 에서 양변을 -3으로 나누어 x = 2 를 구해 모든 과정이 맞다.","suggestion":"풀이가 정확하므로 그대로 두면 된다. 다만 -3으로 나눌 때 부호가 바뀌는 원리를 다시 말로 설명해 보게 하면 개념 정리에 도움이 된다.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s55-5', 's55', 'a-c15-1-p5', '6x = 18', to_timestamp(1794792840), to_timestamp(1794792960), ARRAY['6x=18', 'x=3'], 'done', '{"correctedLines":["6x=18","x=3"],"recognizedAnswer":"x=3","correct":true,"firstErrorLine":null,"errorType":"NONE","concept":"등식의 성질·이항","reason":"6x=18에서 양변을 6으로 나누어 x=3을 얻었고, 검산에서도 해 x=3이 확인된다. 풀이에 오류가 없다.","suggestion":"정답이므로 추가 지도는 필요하지 않다. 다만 등식의 성질을 이용해 양변을 같은 수로 나누는 과정을 말로 설명해 보게 하면 개념 정리에 도움이 된다.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s56-1', 's56', 'a-c15-1-p1', '2x + 3 = 11', to_timestamp(1794793080), to_timestamp(1794793140), ARRAY['2x+3=11', '2x=11+3', '2x=14', 'x=7'], 'done', '{"correctedLines":["2x+3=11","2x=11+3","2x=14","x=7"],"recognizedAnswer":"x=7","correct":false,"firstErrorLine":1,"errorType":"TRANSPOSE","concept":"등식의 성질·이항","reason":"2x+3=11에서 3을 이항할 때 부호를 바꾸지 않아 2x=11+3이 됐다. 올바른 이항은 2x=11-3이다.","suggestion":"등식의 양변에서 같은 수를 빼는 성질을 떠올려, 3을 오른쪽으로 옮길 때 부호가 어떻게 바뀌는지 확인해 보세요.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s56-2', 's56', 'a-c15-1-p10', '3x + 4 = 19', to_timestamp(1794793320), to_timestamp(1794793395), ARRAY['3x+4=19', '3x=19+4', '3x=23', 'x=23/3'], 'done', '{"correctedLines":["3x+4=19","3x=19+4","3x=23","x=23/3"],"recognizedAnswer":"x=23/3","correct":false,"firstErrorLine":1,"errorType":"TRANSPOSE","concept":"등식의 성질·이항","reason":"3x+4=19 에서 4 를 이항할 때 부호를 바꾸지 않아 3x=19+4 가 됐다. 올바른 이항은 3x=19-4 이다.","suggestion":"이항할 때 항의 부호가 바뀌는 이유를 다시 확인해 보세요. 3x+4=19 에서 4 를 오른쪽으로 옮기면 3x=19-4 가 되는지 직접 써 보며 연습해 보세요.","needsReview":false,"model":"solar-pro4-260806"}', '{"memo":"이항하면 부호가 바뀐다는 걸 알지만 급하게 쓰다 잊는다고 함","confirmedAt":1794796920000,"by":"teacher"}'),
  ('demo-c15-s56-3', 's56', 'a-c15-1-p4', '4x - 9 = -1', to_timestamp(1794793560), to_timestamp(1794793650), ARRAY['4x-9=-1', '4x=-1-9', '4x=-10', 'x=-5/2'], 'done', '{"correctedLines":["4x-9=-1","4x=-1-9","4x=-10","x=-5/2"],"recognizedAnswer":"x=-5/2","correct":false,"firstErrorLine":1,"errorType":"TRANSPOSE","concept":"등식의 성질·이항","reason":"4x = -1 - 9 에서 -9를 이항할 때 부호를 바꾸지 않아 -1 - 9가 됐다. 올바르게는 4x = -1 + 9 로 써야 한다.","suggestion":"이항할 때 항의 부호가 바뀌는 이유를 다시 확인해 보세요. 4x - 9 = -1에서 -9를 오른쪽으로 옮기면 +9가 되는지 직접 말해 보게 하세요.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s56-4', 's56', 'a-c15-1-p5', '6x = 18', to_timestamp(1794793800), to_timestamp(1794793905), ARRAY['6x=18', 'x=3'], 'done', '{"correctedLines":["6x=18","x=3"],"recognizedAnswer":"x=3","correct":true,"firstErrorLine":null,"errorType":"NONE","concept":"등식의 성질·이항","reason":"6x=18에서 양변을 6으로 나누어 x=3을 얻었고, 검산에서도 해가 x=3으로 확인되어 과정과 최종 답 모두 맞다.","suggestion":"정답이므로 추가 지도는 필요하지 않다. 다만 등식의 성질을 이용해 계수를 없애는 과정을 말로 설명해 보게 하면 이해를 더 굳힐 수 있다.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s57-1', 's57', 'a-c15-1-p1', '2x + 3 = 11', to_timestamp(1794794040), to_timestamp(1794794100), ARRAY['2x+3=11', '2x=11-3', '2x=8', 'x=4'], 'done', '{"correctedLines":["2x+3=11","2x=11-3","2x=8","x=4"],"recognizedAnswer":"x=4","correct":true,"firstErrorLine":null,"errorType":"NONE","concept":"등식의 성질·이항","reason":"모든 줄이 해설과 일치하며, 3을 이항할 때 부호를 바꾸어 2x=11-3으로 쓰고 2x=8, x=4까지 정확히 구했다.","suggestion":"이항할 때 부호를 바꾸는 이유를 다시 말로 설명해 보게 하면 등식의 성질에 대한 이해가 더 단단해진다. 비슷한 유형의 문제를 한 번 더 풀어 보며 과정을 스스로 점검하게 해도 좋다.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s57-2', 's57', 'a-c15-1-p2', '3x - 5 = -8', to_timestamp(1794794280), to_timestamp(1794794355), ARRAY['3x-5=-8', '3x=-8+5', '3x=-3', 'x=-1'], 'done', '{"correctedLines":["3x-5=-8","3x=-8+5","3x=-3","x=-1"],"recognizedAnswer":"x=-1","correct":true,"firstErrorLine":null,"errorType":"NONE","concept":"등식의 성질·이항","reason":"모든 줄이 검산 기준에서 앞 줄과 같고 최종 답 x=-1이 정답과 일치하므로 오류가 없다.","suggestion":"정답이므로 별도 보충은 필요 없다. 다만 음수 이항(-8+5)과 계수 나누기(3으로 나누기) 과정을 말로 설명해 보게 하면 개념 정리에 도움이 된다.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s57-3', 's57', 'a-c15-1-p6', '2(x + 3) = 14', to_timestamp(1794794520), to_timestamp(1794794610), ARRAY['2(x+3)=14', '2x+6=14', '2x=8', 'x=4'], 'done', '{"correctedLines":["2(x+3)=14","2x+6=14","2x=8","x=4"],"recognizedAnswer":"x=4","correct":true,"firstErrorLine":null,"errorType":"NONE","concept":"분배법칙·동류항 정리","reason":"모든 줄에서 앞 줄과 값이 달라지지 않았고, 분배법칙으로 괄호를 풀고 상수항을 이항한 뒤 계수로 나누어 x=4를 정확히 구했다. 마지막 줄의 답도 정답과 일치한다.","suggestion":"풀이 과정이 정확하므로, 비슷한 형태의 괄호 있는 일차방정식(예: 3(x-2)=15)을 풀어 보며 분배법칙과 이항 순서를 스스로 설명해 보게 하면 좋다.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s57-4', 's57', 'a-c15-1-p8', '-(x + 3) = 5', to_timestamp(1794794760), to_timestamp(1794794865), ARRAY['-(x+3)=5', '-x-3=5', '-x=8', 'x=-8'], 'done', '{"correctedLines":["-(x+3)=5","-x-3=5","-x=8","x=-8"],"recognizedAnswer":"x=-8","correct":true,"firstErrorLine":null,"errorType":"NONE","concept":"분배법칙·동류항 정리","reason":"풀이의 모든 줄이 해설과 일치하며, -(x+3)을 -x-3으로 바르게 풀고 -x=8에서 x=-8을 정확히 구했다.","suggestion":"정답이므로 추가 보충은 필요하지 않다. 다만 -(x+3)에서 괄호 앞 음수가 괄호 안 모든 항의 부호를 바꾼다는 점을 다시 확인해 보면 좋다.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s57-5', 's57', 'a-c15-1-p14', '사과가 x 개 있고, 배는 사과보다 3개 많아요. 사과와 배가 모두 13개일 때, 배는 몇 개인지 구하세요.', to_timestamp(1794795000), to_timestamp(1794795120), ARRAY['x+(x+3)=13', '2x=10', 'x=5', 'x+3=8', '8개'], 'done', '{"correctedLines":["x+(x+3)=13","2x=10","x=5","x+3=8","8개"],"recognizedAnswer":"8개","correct":true,"firstErrorLine":null,"errorType":"NONE","concept":"일차방정식의 활용","reason":"식 세우기부터 이항, 동류항 정리, 계수 나누기, 구하는 값(배의 개수) 계산까지 모든 과정이 정확하며 최종 답도 정답과 일치한다.","suggestion":"풀이 과정이 모두 맞으므로 추가 보충은 필요하지 않다. 다만 구한 x=5가 사과 개수이고, 문제에서 묻는 것은 배의 개수임을 다시 확인하게 하면 좋다.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s58-1', 's58', 'a-c15-1-p1', '2x + 3 = 11', to_timestamp(1794795240), to_timestamp(1794795300), ARRAY['27c+3=11', '2つし=11-3', '2つし=6', 'つく=3'], 'done', '{"correctedLines":["2x+3=11","2x=11-3","2x=6","x=3"],"recognizedAnswer":"x=3","correct":false,"firstErrorLine":2,"errorType":"ARITH","concept":"등식의 성질·이항","reason":"2x = 11 - 3 에서 11 - 3 을 6 으로 잘못 계산하여 2x = 6 이 되었다. 맞는 값은 8 이므로 2x = 8 이어야 한다.","suggestion":"11 - 3 을 다시 계산해 보고, 2x = 8 이 맞는지 확인해 보세요. 그다음 양변을 2 로 나누어 x = 4 를 구하면 됩니다.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s58-2', 's58', 'a-c15-1-p10', '3x + 4 = 19', to_timestamp(1794795480), to_timestamp(1794795555), ARRAY['3フレ+4=19', '3フレ=19-4', '3フレ=14', 'フレ=14/3'], 'done', '{"correctedLines":["3x+4=19","3x=19-4","3x=14","x=14/3"],"recognizedAnswer":"x=14/3","correct":false,"firstErrorLine":2,"errorType":"ARITH","concept":"등식의 성질·이항","reason":"3x = 19 - 4 에서 19 - 4 를 15가 아닌 14로 잘못 계산했다. 양수끼리 하는 단순 뺄셈을 틀린 계산 실수다.","suggestion":"19 - 4 를 다시 계산해 보고, 3x = 15 가 맞는지 확인해 보라고 물어본다. 이후 3x = 15 에서 양변을 3으로 나누어 x = 5 를 구하는 과정도 함께 점검한다.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s58-3', 's58', 'a-c15-1-p5', '6x = 18', to_timestamp(1794795720), to_timestamp(1794795810), ARRAY['6つく=18', 'つく=3'], 'done', '{"correctedLines":["6x=18","x=3"],"recognizedAnswer":"x=3","correct":true,"firstErrorLine":null,"errorType":"NONE","concept":"등식의 성질·이항","reason":"6x=18에서 양변을 6으로 나누어 x=3을 얻었고, 검산에서도 해가 x=3으로 확인된다. 풀이에 오류가 없으며 정답이다.","suggestion":"정답이므로 별도의 보충 지도는 필요하지 않다. 다만 등식의 성질을 이용해 계수를 나누는 과정을 말로 설명해 보게 하면 이해를 더 굳힐 수 있다.","needsReview":false,"model":"solar-pro4-260806"}', NULL),
  ('demo-c15-s58-4', 's58', 'a-c15-1-p4', '4x - 9 = -1', to_timestamp(1794795960), to_timestamp(1794796065), ARRAY['4x-9=-1', '4x=-1+9', '4x=8', 'x=2'], 'done', '{"correctedLines":["4x-9=-1","4x=-1+9","4x=8","x=2"],"recognizedAnswer":"x=2","correct":true,"firstErrorLine":null,"errorType":"NONE","concept":"등식의 성질·이항","reason":"모든 줄에서 등식의 성질에 따라 이항과 동류항 정리를 정확히 했고, 마지막 줄의 답 x=2도 정답과 일치한다. 중간 과정에 오류나 부호 실수가 없다.","suggestion":"정답이므로 별도의 보충 지도는 필요하지 않다. 다만 비슷한 유형의 음수 이항 문제를 몇 개 더 풀어 보며 부호 처리 습관을 확인해 보면 좋다.","needsReview":false,"model":"solar-pro4-260806"}', NULL)
